#include <stdio.h>
#include <stdlib.h>
#include <errno.h>
#include <limits.h>

int main(int argc, char *argv[])
{
    /* No argument */
    if (argc < 2) {
        puts("NO_INPUT");
        return 0;
    }

    /* Parse integer */
    char *endptr = NULL;
    errno = 0;
    long n = strtol(argv[1], &endptr, 10);

    /* Bad input: no digits or extra characters */
    if (endptr == argv[1] || *endptr != '\0') {
        puts("BAD_INPUT");
        return 0;
    }

    /* Out of allowed range (n must be >= 1 and <= 1,000,000) */
    if (n < 1 || n > 1000000L) {
        puts("OUT_OF_RANGE");
        return 0;
    }

    /* Compute sum of proper divisors */
    long sum = 0;
    for (long d = 1; d < n; ++d) {
        if (n % d == 0) {
            sum += d;
        }
    }

    if (sum == n) {
        printf("n=%ld sum=%ld perfect\n", n, sum);
    } else if (sum > n) {
        printf("n=%ld sum=%ld abundant\n", n, sum);
    } else {
        printf("n=%ld sum=%ld deficient\n", n, sum);
    }
    return 0;
}
